<script setup lang="ts">
import { ref } from 'vue'
import { PhArrowLeft, PhMagicWand, PhNotebook, PhTreeStructure } from '@phosphor-icons/vue'
import { command } from '../api'
const transcript = ref('本次组会讨论了多 Agent 路由的验证方案。\n需要：周五前补充压力测试数据。\n待办：整理答辩演示流程。'); const loading = ref(false); const error = ref('')
const note = ref<{ three_sentence_summary: string[]; markdown_knowledge_tree: string; todo_items: Array<{ task: string; timestamp_seconds: number }> } | null>(null)
async function organize() { loading.value = true; error.value = ''; const segments = transcript.value.split('\n').filter(Boolean).map((text, index) => ({ start_seconds: index * 20, end_seconds: index * 20 + 19, text })); try { note.value = (await command('academic', 'organize_transcript', '', { segments })).data as typeof note.value } catch (reason) { error.value = reason instanceof Error ? reason.message : '整理失败' } finally { loading.value = false } }
</script>
<template><section class="notes-studio"><RouterLink to="/academic"><PhArrowLeft :size="18" /> 返回功能选择</RouterLink><header><div><PhNotebook :size="36" weight="duotone" /><h1>把一段杂乱记录，<br><em>整理成下一步。</em></h1></div><p>当前支持文本转录片段。真实录音上传与 STT 仍需配置语音服务商。</p></header><div class="notes-desk"><article class="source-paper"><label>课堂或组会转录<textarea v-model="transcript" placeholder="每行可以作为一个时间片段…"></textarea></label><button type="button" :disabled="loading" @click="organize"><PhMagicWand :size="19" /> {{ loading ? '正在整理' : '生成结构化笔记' }}</button></article><article class="organized-paper"><div v-if="note"><section><h2>三句摘要</h2><ol><li v-for="line in note.three_sentence_summary" :key="line">{{ line }}</li></ol></section><section><h2>待办清单</h2><ul><li v-for="item in note.todo_items" :key="item.task"><span>{{ item.timestamp_seconds }}s</span>{{ item.task }}</li></ul></section><section><h2><PhTreeStructure :size="20" /> Markdown 知识树</h2><pre>{{ note.markdown_knowledge_tree }}</pre></section></div><div v-else class="notes-empty"><PhTreeStructure :size="42" weight="duotone" /><strong>整理结果会出现在这里</strong><p>不补写原文中不存在的事实。</p></div></article></div><p v-if="error" class="inline-error">{{ error }}</p></section></template>
